const data = $input.first().json;

const workflowName = (data.workflow && data.workflow.name) || 'Unknown Workflow';
const executionId = (data.execution && data.execution.id) || '';
const failedNode = (data.execution && data.execution.lastNodeExecuted) || 'Unknown Node';

let errorMessage = 'Unknown error';
try {
  if (data.execution && data.execution.error) {
    errorMessage = data.execution.error.message || JSON.stringify(data.execution.error);
  }
} catch (e) {
  errorMessage = 'Could not parse error details';
}

return [{
  json: {
    workflowName,
    executionId,
    failedNode,
    errorMessage,
    timestamp: new Date().toISOString()
  }
}];

